using StainedGlass.Core;
using System.Reflection;
int passed=0,failed=0;
void Check(string name,int expected,Func<int> actual) {try {var got=actual();bool ok=got==expected;Console.WriteLine($"{(ok?"PASS":"FAIL")} {name}: expected {expected}, actual {got}");if(ok)passed++;else failed++;}catch(Exception e){failed++;Console.WriteLine($"FAIL {name}: {e.GetType().Name}");}}
int Score(string o,DieCell?[,] g)=>ScoringEngine.CalculatePublicObjectives(o,null,null,g);
DieCell?[,] Grid(params (int row,int col,int? value,string? color)[] dice) {var g=new DieCell?[4,5];foreach(var d in dice)g[d.row,d.col]=new(d.value,d.color);return g;}
var colors=new[]{"Red","Yellow","Green","Blue","Purple"};
Check("Empty real board penalty",20,()=>ScoringEngine.CountEmptySpaces(Grid()));
var full=Grid();for(int r=0;r<4;r++)for(int c=0;c<5;c++) full[r,c]=new((r+c)%6+1,colors[(r+c)%5]);
Check("Full real board empty penalty",0,()=>ScoringEngine.CountEmptySpaces(full));
Check("Four distinct shades in each real column",20,()=>Score(ScoringEngine.ObjectiveColumnShadeVariety,full));
Check("Four complete color rows",24,()=>Score(ScoringEngine.ObjectiveRowColorVariety,full));
Check("Four complete shade rows",20,()=>Score(ScoringEngine.ObjectiveRowShadeVariety,full));
Check("Column Color Variety supported",1,()=>typeof(ScoringEngine).GetFields(BindingFlags.Public|BindingFlags.Static).Count(f=>f.Name=="ObjectiveColumnColorVariety"));
Check("Native 4x5 board accepted for row objective",24,()=>{var g=new DieCell?[4,5];for(int r=0;r<4;r++)for(int c=0;c<5;c++)g[r,c]=full[r,c];return Score(ScoringEngine.ObjectiveRowColorVariety,g);});
var values=Grid((0,0,1,"Red"),(0,2,2,"Blue"),(1,1,3,"Green"),(1,3,4,"Yellow"),(2,0,5,"Purple"),(2,2,6,"Red"));
Check("Shade variety one set",5,()=>Score(ScoringEngine.ObjectiveShadeVariety,values));
Check("Color variety one set",4,()=>Score(ScoringEngine.ObjectiveColorVariety,values));
Check("Light pair",2,()=>Score(ScoringEngine.ObjectiveLightShade,values));
Check("Medium pair",2,()=>Score(ScoringEngine.ObjectiveMediumShade,values));
Check("Deep pair",2,()=>Score(ScoringEngine.ObjectiveDeepShades,values));
Check("Private red sum",7,()=>ScoringEngine.CalculatePrivateObjective(ScoringEngine.PrivateShadesRed,values));
Check("Private objective ignores other colors",5,()=>ScoringEngine.CalculatePrivateObjective(ScoringEngine.PrivateShadesPurple,values));
var cross=Grid((0,0,1,"Red"),(0,2,2,"Red"),(1,1,3,"Red"),(2,0,4,"Red"),(2,2,5,"Red"));
Check("Diagonal crossing counts each die once",5,()=>Score(ScoringEngine.ObjectiveColorDiagonals,cross));
Check("Orthogonal pair not a diagonal",0,()=>Score(ScoringEngine.ObjectiveColorDiagonals,Grid((0,0,1,"Red"),(0,1,2,"Red"))));
Check("Uneven light sets",2,()=>Score(ScoringEngine.ObjectiveLightShade,Grid((0,0,1,"Red"),(0,2,1,"Blue"),(1,1,2,"Green"))));
Check("Incomplete shade-only input must not earn pairs",0,()=>Score(ScoringEngine.ObjectiveLightShade,Grid((0,0,1,null),(1,1,2,null))));
var partial=Grid();for(int c=0;c<5;c++)partial[0,c]=new(null,colors[c]);
Check("Incomplete color-only row must not score",0,()=>Score(ScoringEngine.ObjectiveRowColorVariety,partial));
Check("Duplicate public card must not multiply score",2,()=>ScoringEngine.CalculatePublicObjectives(ScoringEngine.ObjectiveLightShade,ScoringEngine.ObjectiveLightShade,ScoringEngine.ObjectiveLightShade,values));
Check("Favor tokens",3,()=>ScoringEngine.ParseFavorTokens("3"));
Check("Negative favors",0,()=>ScoringEngine.ParseFavorTokens("-1"));
Check("Blank objective",0,()=>Score(ScoringEngine.ObjectiveBlank,values));
Check("Public cards scored independently",9,()=>ScoringEngine.CalculatePublicObjectives(ScoringEngine.ObjectiveLightShade,ScoringEngine.ObjectiveMediumShade,ScoringEngine.ObjectiveShadeVariety,values));
Check("Five complete color columns",25,()=>Score(ScoringEngine.ObjectiveColumnColorVariety,full));
full[0,0]=null;
Check("Incomplete column excluded",20,()=>Score(ScoringEngine.ObjectiveColumnColorVariety,full));
Check("Partial input produces validation error",1,()=>ScoringEngine.GetInputError(partial) is null ? 0 : 1);
Check("Duplicate selection produces validation error",1,()=>ScoringEngine.GetInputError(values,ScoringEngine.ObjectiveLightShade,ScoringEngine.ObjectiveLightShade) is null ? 0 : 1);
Check("Valid selection accepted",1,()=>ScoringEngine.GetInputError(values,ScoringEngine.ObjectiveLightShade,ScoringEngine.ObjectiveMediumShade) is null ? 1 : 0);
Console.WriteLine($"TOTAL {passed} passed, {failed} failed");
Environment.ExitCode = failed == 0 ? 0 : 1;
